using System;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;using ElementalHearts;using Verse;
class AwakeningRegression {
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}static void Check(bool ok,string label){if(!ok)throw new Exception(label);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(AwakeningRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  for(int b=0;b<4096;b++){bool h=(b&1)!=0,m=(b&2)!=0,a=(b&4)!=0,p=(b&8)!=0,f=(b&16)!=0,d=(b&32)!=0,down=(b&64)!=0,v=(b&128)!=0,pr=(b&256)!=0,sl=(b&512)!=0,e=(b&1024)!=0;Check(NpcDiscipleRules.SpawnEligible(h,m,a,p,f,d,down,v,pr,sl,e)==(h&&!m&&a&&!p&&f&&!d&&!down&&v&&!pr&&!sl&&!e),"NPC generation eligibility differs");}
  int rolls=0;for(int b=0;b<32;b++){bool d=(b&1)!=0,t=(b&2)!=0,l=(b&4)!=0,c=(b&8)!=0,h=(b&16)!=0;bool yes=NpcDiscipleRules.ShouldRoll(d,t,l,c,h);Check(yes==(d&&!t&&l&&c&&h),"awakening eligibility differs");if(yes)rolls++;}Check(rolls==1&&NpcDiscipleRules.AwakeningChance==.05f&&NpcDiscipleRules.CriticalHealth==.25f&&NpcDiscipleRules.GraceTicks==180,"awakening tuning changed");Check(new ElementalHeartsSettings().npcDiscipleChance==.2f&&NpcDisciples.Elements.Length==5,"NPC default rate/elements incorrect");
  var pawn=Empty<Pawn>();var other=Empty<Pawn>();var frame=new AwakeningHit{pawn=pawn,queued=true};var context=typeof(DiscipleAwakening).GetField("current",BindingFlags.Static|BindingFlags.NonPublic);context.SetValue(null,frame);try{Check(DiscipleAwakening.HoldState(pawn,false)&&DiscipleAwakening.HoldState(pawn,true)&&!DiscipleAwakening.HoldState(other,true),"fatal hold leaks to another pawn");frame.queued=false;frame.committing=true;Check(DiscipleAwakening.HoldState(pawn,false),"atomic repair not guarded");}finally{context.SetValue(null,null);}Check(!DiscipleAwakening.HoldState(pawn,true),"fatal guard remains after scope");var error=new Exception("fixture");Check(object.ReferenceEquals(DiscipleAwakening.Finish(null,error),error),"unrelated exception replaced");
  var comp=new HediffComp_ElementalApprentice{discipleKills=27,awakeningRolled=true};var payload=new AwakeningSaveCase{comp=comp};string file=Path.Combine(Path.GetTempPath(),"Awakening_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"AwakeningTest");Scribe_Deep.Look(ref payload,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectSingleNode("AwakeningTest/state/EH_discipleKills").InnerText=="27"&&xml.SelectSingleNode("AwakeningTest/state/EH_awakeningRolled").InnerText=="True","saved one-time roll or old kill count lost");File.Delete(file);
  Console.WriteLine("PASS: adult humanlike faction generation filters, 20% default/five elements, one 5% critical-combat roll, pawn-local atomic death hold and unchanged exception propagation.");Console.WriteLine("PASS: native Scribe output retains disciple kills and the saved one-time awakening decision.");
 }
}
public class AwakeningSaveCase:IExposable {public HediffComp_ElementalApprentice comp;public void ExposeData(){comp.CompExposeData();}}
